/**
 * Manages hover interactions across multiple chart instances.
 *
 * Each mounted chart owns a local hover state. When `syncHover` is enabled the
 * hover position is shared across every mounted instance instead, so hovering
 * one chart highlights the same index on all of them. The sync preferences
 * (`syncHover` / `syncTooltip`) are shared globally and persisted to
 * localStorage so they survive page reloads.
 */

export const HOVER_SYNC_STORAGE_KEY = 'supabase-chart-hover-sync-enabled'
export const TOOLTIP_SYNC_STORAGE_KEY = 'supabase-chart-tooltip-sync-enabled'

export interface ChartHoverState {
  /** Currently hovered data index, or null when nothing is hovered. */
  hoveredIndex: number | null
  /** Id of the chart that originated the current hover, or null. */
  hoveredChart: string | null
  /** True when there is an active hover (a non-null hovered index). */
  isHovered: boolean
  /** True only for the chart instance that owns the current hover. */
  isCurrentChart: boolean
  /** Whether hover position is synchronized across chart instances. */
  syncHover: boolean
  /** Whether tooltips are synchronized across chart instances. */
  syncTooltip: boolean
  /** Set the hovered index for this chart (local or global based on syncHover). */
  setHover: (index: number | null) => void
  /** Clear the hover state (local or global based on syncHover). */
  clearHover: () => void
  /** Enable/disable hover synchronization for all instances (persisted). */
  setSyncHover: (enabled: boolean) => void
  /** Enable/disable tooltip synchronization for all instances (persisted). */
  setSyncTooltip: (enabled: boolean) => void
}

interface HoverPosition {
  hoveredIndex: number | null
  hoveredChart: string | null
}

interface SyncPreferences {
  syncHover: boolean
  syncTooltip: boolean
}

const emptyHoverPosition = (): HoverPosition => ({ hoveredIndex: null, hoveredChart: null })

/**
 * Reads the persisted sync preferences from localStorage. Any corrupted or
 * non-JSON-parseable value causes both preferences to fall back to `false`
 * and emits a console warning.
 */
const readSyncPreferences = (): SyncPreferences => {
  if (typeof window === 'undefined' || typeof localStorage === 'undefined') {
    return { syncHover: false, syncTooltip: false }
  }

  try {
    const rawHover = localStorage.getItem(HOVER_SYNC_STORAGE_KEY)
    const rawTooltip = localStorage.getItem(TOOLTIP_SYNC_STORAGE_KEY)

    return {
      syncHover: rawHover === null ? false : Boolean(JSON.parse(rawHover)),
      syncTooltip: rawTooltip === null ? false : Boolean(JSON.parse(rawTooltip)),
    }
  } catch (error) {
    console.warn('Failed to read chart hover sync setting from localStorage:', error)
    return { syncHover: false, syncTooltip: false }
  }
}

// Module-level store shared by every hook instance.
let hoverPosition: HoverPosition = emptyHoverPosition()
let syncPreferences: SyncPreferences = readSyncPreferences()

const listeners = new Set<() => void>()

const notify = () => {
  listeners.forEach((listener) => listener())
}

const persist = (syncHover: boolean, syncTooltip: boolean) => {
  try {
    localStorage.setItem(HOVER_SYNC_STORAGE_KEY, JSON.stringify(syncHover))
    localStorage.setItem(TOOLTIP_SYNC_STORAGE_KEY, JSON.stringify(syncTooltip))
  } catch (error) {
    console.warn('Failed to save chart hover sync setting to localStorage:', error)
  }
}

const setHoverGlobal = (chartId: string, index: number | null) => {
  hoverPosition = { hoveredIndex: index, hoveredChart: chartId }
  notify()
}

const clearHoverGlobal = () => {
  hoverPosition = emptyHoverPosition()
  notify()
}

const setSyncHoverGlobal = (enabled: boolean) => {
  // No-op when the requested state already matches the current state.
  if (syncPreferences.syncHover === enabled) return

  // Disabling hover sync also disables tooltip sync.
  const nextSyncTooltip = enabled ? syncPreferences.syncTooltip : false

  // Update the in-memory state first so it applies even if persistence fails.
  syncPreferences = { syncHover: enabled, syncTooltip: nextSyncTooltip }
  persist(enabled, nextSyncTooltip)
  notify()
}

const setSyncTooltipGlobal = (enabled: boolean) => {
  // Enabling tooltip sync also enables hover sync.
  const nextSyncHover = enabled ? true : syncPreferences.syncHover

  // No-op when nothing would actually change.
  if (syncPreferences.syncTooltip === enabled && syncPreferences.syncHover === nextSyncHover) {
    return
  }

  syncPreferences = { syncHover: nextSyncHover, syncTooltip: enabled }
  persist(nextSyncHover, enabled)
  notify()
}

let chartIdCounter = 0

export function useChartHoverState(chartId?: string): ChartHoverState {
  // Ensure every instance has a stable id, even when none is provided.
  const generatedId = useRef<string>()
  if (!generatedId.current) {
    generatedId.current = `chart-${(chartIdCounter += 1)}`
  }
  const id = chartId ?? generatedId.current

  const [, forceRender] = useReducer((count: number) => count + 1, 0)

  // Local (unsynchronized) hover position for this instance.
  const localHover = useRef<HoverPosition>(emptyHoverPosition())

  useEffect(() => {
    // When no instances are mounted, reload persisted preferences and reset the
    // shared hover position so a fresh set of charts starts from a clean slate.
    if (listeners.size === 0) {
      syncPreferences = readSyncPreferences()
      hoverPosition = emptyHoverPosition()
    }

    const listener = () => forceRender()
    listeners.add(listener)

    // Reflect any state reloaded above on this instance.
    forceRender()

    return () => {
      listeners.delete(listener)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const setHover = useCallback(
    (index: number | null) => {
      if (syncPreferences.syncHover) {
        setHoverGlobal(id, index)
      } else {
        localHover.current = { hoveredIndex: index, hoveredChart: id }
        forceRender()
      }
    },
    [id]
  )

  const clearHover = useCallback(() => {
    if (syncPreferences.syncHover) {
      clearHoverGlobal()
    } else {
      localHover.current = emptyHoverPosition()
      forceRender()
    }
  }, [])

  const setSyncHover = useCallback((enabled: boolean) => {
    setSyncHoverGlobal(enabled)
  }, [])

  const setSyncTooltip = useCallback((enabled: boolean) => {
    setSyncTooltipGlobal(enabled)
  }, [])

  const { syncHover, syncTooltip } = syncPreferences
  const activeHover = syncHover ? hoverPosition : localHover.current

  const hoveredIndex = activeHover.hoveredIndex
  const hoveredChart = activeHover.hoveredChart

  return {
    hoveredIndex,
    hoveredChart,
    isHovered: hoveredIndex !== null,
    isCurrentChart: hoveredChart !== null && hoveredChart === id,
    syncHover,
    syncTooltip,
    setHover,
    clearHover,
    setSyncHover,
    setSyncTooltip,
  }
}

/**
 * Resets the shared hover store. Primarily useful for tests that need to
 * guarantee isolation between cases.
 */
export function resetChartHoverState() {
  hoverPosition = emptyHoverPosition()
  syncPreferences = { syncHover: false, syncTooltip: false }
  listeners.clear()
}
