import { describe, it, expect, beforeEach, vi } from 'vitest'
import {
  useChartHoverState,
  HOVER_SYNC_STORAGE_KEY,
  TOOLTIP_SYNC_STORAGE_KEY,
} from './useChartHoverState'

describe('useChartHoverState smoke', () => {
  beforeEach(() => {
    localStorage.clear()
    vi.restoreAllMocks()
  })

  it('default state', () => {
    const { result } = renderHook(() => useChartHoverState('c1'))
    expect(result.current.hoveredIndex).toBe(null)
    expect(result.current.hoveredChart).toBe(null)
    expect(result.current.isHovered).toBe(false)
    expect(result.current.isCurrentChart).toBe(false)
    expect(result.current.syncHover).toBe(false)
    expect(result.current.syncTooltip).toBe(false)
  })

  it('reads persisted prefs', () => {
    localStorage.setItem(HOVER_SYNC_STORAGE_KEY, 'true')
    localStorage.setItem(TOOLTIP_SYNC_STORAGE_KEY, 'true')
    const { result } = renderHook(() => useChartHoverState('c1'))
    expect(result.current.syncHover).toBe(true)
    expect(result.current.syncTooltip).toBe(true)
  })

  it('corrupted prefs default to false and warn', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    localStorage.setItem(HOVER_SYNC_STORAGE_KEY, 'not-json{')
    const { result } = renderHook(() => useChartHoverState('c1'))
    expect(result.current.syncHover).toBe(false)
    expect(result.current.syncTooltip).toBe(false)
    expect(warn).toHaveBeenCalled()
  })

  it('local hover only affects the caller', () => {
    const a = renderHook(() => useChartHoverState('a'))
    const b = renderHook(() => useChartHoverState('b'))
    act(() => a.result.current.setHover(3))
    expect(a.result.current.hoveredIndex).toBe(3)
    expect(a.result.current.isHovered).toBe(true)
    expect(a.result.current.isCurrentChart).toBe(true)
    // b unsynced, unaffected
    expect(b.result.current.hoveredIndex).toBe(null)
    expect(b.result.current.isCurrentChart).toBe(false)
  })

  it('synced hover reflects across instances, isCurrentChart only for caller', () => {
    const a = renderHook(() => useChartHoverState('a'))
    const b = renderHook(() => useChartHoverState('b'))
    act(() => a.result.current.setSyncHover(true))
    act(() => a.result.current.setHover(7))
    expect(a.result.current.hoveredIndex).toBe(7)
    expect(b.result.current.hoveredIndex).toBe(7)
    expect(a.result.current.isHovered).toBe(true)
    expect(b.result.current.isHovered).toBe(true)
    expect(a.result.current.isCurrentChart).toBe(true)
    expect(b.result.current.isCurrentChart).toBe(false)
    act(() => b.result.current.clearHover())
    expect(a.result.current.hoveredIndex).toBe(null)
    expect(b.result.current.hoveredIndex).toBe(null)
  })

  it('setSyncHover persists and disabling clears tooltip', () => {
    const { result } = renderHook(() => useChartHoverState('c1'))
    act(() => result.current.setSyncTooltip(true))
    expect(result.current.syncHover).toBe(true)
    expect(result.current.syncTooltip).toBe(true)
    expect(JSON.parse(localStorage.getItem(HOVER_SYNC_STORAGE_KEY)!)).toBe(true)
    expect(JSON.parse(localStorage.getItem(TOOLTIP_SYNC_STORAGE_KEY)!)).toBe(true)
    act(() => result.current.setSyncHover(false))
    expect(result.current.syncHover).toBe(false)
    expect(result.current.syncTooltip).toBe(false)
  })

  it('no-op when setSyncHover matches', () => {
    const { result } = renderHook(() => useChartHoverState('c1'))
    const spy = vi.spyOn(Storage.prototype, 'setItem')
    act(() => result.current.setSyncHover(false))
    expect(spy).not.toHaveBeenCalled()
  })

  it('localStorage save failure warns but updates memory', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => {
      throw new Error('quota')
    })
    const { result } = renderHook(() => useChartHoverState('c1'))
    act(() => result.current.setSyncHover(true))
    expect(result.current.syncHover).toBe(true)
    expect(warn).toHaveBeenCalledWith(
      'Failed to save chart hover sync setting to localStorage:',
      expect.any(Error)
    )
  })

  it('rapid calls reflect final state', () => {
    const { result } = renderHook(() => useChartHoverState('c1'))
    act(() => {
      result.current.setHover(1)
      result.current.setHover(2)
      result.current.clearHover()
      result.current.setHover(9)
    })
    expect(result.current.hoveredIndex).toBe(9)
  })
})
